package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

// CacheNode represents a node in the distributed cache cluster
type CacheNode struct {
	Address  string
	Weight   int
	Healthy  bool
	LastSeen time.Time
}

// UploadMetadata stores metadata about uploaded files
type UploadMetadata struct {
	Filename    string
	ContentType string
	Size        int64
	Checksum    string
	RedirectURI string
	CachedAt    time.Time
}

// CacheCluster manages distributed cache nodes
type CacheCluster struct {
	mu       sync.RWMutex
	nodes    []CacheNode
	uploads  map[string]*UploadMetadata
	allowedHosts []string
}

func NewCacheCluster(allowedHosts []string) *CacheCluster {
	return &CacheCluster{
		nodes: []CacheNode{
			{Address: "cache-1.internal:6379", Weight: 10, Healthy: true},
			{Address: "cache-2.internal:6379", Weight: 10, Healthy: true},
			{Address: "cache-3.internal:6379", Weight: 5, Healthy: true},
		},
		uploads:      make(map[string]*UploadMetadata),
		allowedHosts: allowedHosts,
	}
}

// computeChecksum generates a SHA-256 checksum for content
func computeChecksum(data []byte) string {
	h := sha256.Sum256(data)
	return hex.EncodeToString(h[:])
}

// selectNode picks a cache node based on consistent hashing
func (cc *CacheCluster) selectNode(key string) *CacheNode {
	cc.mu.RLock()
	defer cc.mu.RUnlock()

	h := sha256.Sum256([]byte(key))
	idx := int(h[0]) % len(cc.nodes)
	for i := 0; i < len(cc.nodes); i++ {
		candidate := &cc.nodes[(idx+i)%len(cc.nodes)]
		if candidate.Healthy {
			return candidate
		}
	}
	return &cc.nodes[0]
}

// validateRedirectTarget checks if the redirect URI is safe
func (cc *CacheCluster) validateRedirectTarget(rawURI string) (string, error) {
	if rawURI == "" {
		return "/uploads/complete", nil
	}

	// Normalize the URI before parsing
	normalized := strings.TrimSpace(rawURI)

	// Block protocol-relative URLs and schemes other than relative paths
	if strings.HasPrefix(normalized, "//") || strings.Contains(normalized, ":") {
		// Only allow if it matches our strict pattern
		parsed, err := url.Parse(normalized)
		if err != nil {
			return "", fmt.Errorf("invalid redirect URI: %w", err)
		}
		if parsed.Scheme != "" && parsed.Scheme != "https" {
			return "", fmt.Errorf("only https scheme allowed")
		}
		for _, allowed := range cc.allowedHosts {
			if strings.EqualFold(parsed.Host, allowed) {
				return normalized, nil
			}
		}
		return "", fmt.Errorf("redirect host %q not in allowlist", parsed.Host)
	}

	// Parse the URL to validate it
	parsed, err := url.Parse(normalized)
	if err != nil {
		return "", fmt.Errorf("invalid redirect URI: %w", err)
	}

	// Must be a relative path with no host
	if parsed.Host != "" {
		return "", fmt.Errorf("redirect host %q not in allowlist", parsed.Host)
	}

	// Ensure path starts with / and doesn't contain backslashes
	if !strings.HasPrefix(parsed.Path, "/") || strings.Contains(normalized, "\\") {
		return "", fmt.Errorf("invalid relative path")
	}

	return parsed.Path, nil
}

// HandleUpload processes file uploads and caches metadata
func (cc *CacheCluster) HandleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Limit upload size to 10MB
	r.Body = http.MaxBytesReader(w, r.Body, 10<<20)

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "Failed to read upload", http.StatusBadRequest)
		return
	}
	defer file.Close()

	data, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Failed to read file content", http.StatusInternalServerError)
		return
	}

	checksum := computeChecksum(data)
	node := cc.selectNode(checksum)

	// Get the redirect URI from form data
	redirectURI := r.FormValue("callback_url")

	// Validate the redirect target
	safeURI, err := cc.validateRedirectTarget(redirectURI)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	meta := &UploadMetadata{
		Filename:    header.Filename,
		ContentType: header.Header.Get("Content-Type"),
		Size:        int64(len(data)),
		Checksum:    checksum,
		RedirectURI: safeURI,
		CachedAt:    time.Now(),
	}

	cc.mu.Lock()
	cc.uploads[checksum] = meta
	cc.mu.Unlock()

	_ = node // In production, would store to this node

	// Redirect to the callback URL after successful upload
	http.Redirect(w, r, safeURI, http.StatusFound)
}

// HandleStatus returns cache cluster status
func (cc *CacheCluster) HandleStatus(w http.ResponseWriter, r *http.Request) {
	cc.mu.RLock()
	defer cc.mu.RUnlock()

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"nodes": %d, "uploads": %d}`, len(cc.nodes), len(cc.uploads))
}

func main() {
	allowedHosts := []string{
		"app.example.com",
		"cdn.example.com",
		"api.example.com",
	}

	cluster := NewCacheCluster(allowedHosts)

	mux := http.NewServeMux()
	mux.HandleFunc("/upload", cluster.HandleUpload)
	mux.HandleFunc("/status", cluster.HandleStatus)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	fmt.Println("Cache cluster client listening on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
